import { TAB_MESSAGE_TYPES } from './constants'
import {
  SUPPORTED_APP_DOMAINS,
  RESUME_IO_DOMAIN,
  EXTENSION_LOGIN_PATH,
  CAREER_IO_APP_DOMAIN,
  SIGN_IN_PATH,
  CAREER_IO_TR_APP_DOMAIN,
  CAREER_IO_CAREER_MINDS_APP_DOMAIN,
  TOP_CV_APP_DOMAIN,
} from '../shared/constants'

const extractJwt = (): void => {
  const jwtElt = document.getElementById('token') as HTMLInputElement
  const refreshJwtElt = document.getElementById('refresh_token') as HTMLInputElement
  const token = jwtElt ? jwtElt.value : ''
  const refreshToken = refreshJwtElt ? refreshJwtElt.value : ''
  const baseDomain = SUPPORTED_APP_DOMAINS.find((el) => window.location.href.includes(el))
  const isRioPage = baseDomain === RESUME_IO_DOMAIN
  const tokenMissing = token === '' && refreshToken === ''

  if (!baseDomain) {
    throw Error('Not supported domain')
  }

  if (!tokenMissing) {
    chrome.runtime.sendMessage(
      {
        type: TAB_MESSAGE_TYPES.auth,
        token,
        refreshToken,
        isRioUser: isRioPage,
        baseDomain,
      },
      function (response) {
        const domainPrefix = isRioPage ? 'Resume.io' : 'Career.io'
        window.open('', '_self', '')
        window.alert(`Your ${domainPrefix}: Job Tracker is ready to use!
        1. Find job postings online
        2. Click on ${domainPrefix}: Job Search Tracker Extension icon
        3. Save your job to ${domainPrefix} Job Tracker`)
        window.close()
      },
    )
    return
  }
  switch (true) {
    case baseDomain === CAREER_IO_APP_DOMAIN && window.location.href.includes(SIGN_IN_PATH):
      window.open(`${RESUME_IO_DOMAIN}${EXTENSION_LOGIN_PATH}`, '_self')
      break
    case baseDomain === RESUME_IO_DOMAIN && window.location.href.includes(SIGN_IN_PATH):
      window.open(`${CAREER_IO_TR_APP_DOMAIN}${EXTENSION_LOGIN_PATH}`, '_self')
      break
    case baseDomain === CAREER_IO_TR_APP_DOMAIN && window.location.href.includes(SIGN_IN_PATH):
      window.open(`${CAREER_IO_CAREER_MINDS_APP_DOMAIN}${EXTENSION_LOGIN_PATH}`, '_self')
      break
    case baseDomain === CAREER_IO_CAREER_MINDS_APP_DOMAIN &&
      window.location.href.includes(SIGN_IN_PATH):
      window.open(`${TOP_CV_APP_DOMAIN}${EXTENSION_LOGIN_PATH}`, '_self')
      break
    case baseDomain === TOP_CV_APP_DOMAIN && window.location.href.includes(SIGN_IN_PATH):
      // NO ACCESS
      break

    default:
      break
  }
}

export default extractJwt
