import { BaseAutofillStrategy } from './baseAutofill.strategy'
import { CommonAutofillStrategy } from './common.strategy'
import { GreenHouseAutofillStrategy } from './greenhouse.strategy'
import { LeverAutofillStrategy } from './lever.strategy'

// Add more specific job board strategies
const jobBoardsStrategies = [new GreenHouseAutofillStrategy(), new LeverAutofillStrategy()]
// If no strategy found for the job board that page belongs a common strategy will run
const commonStrategy = new CommonAutofillStrategy()

const strategies: BaseAutofillStrategy[] = [...jobBoardsStrategies, commonStrategy]

export default strategies
