import { DEFAULT_COVER_LATTER_NAME, DEFAULT_RESUME_NAME, RESUME_FORMAT } from '../shared/constants'
import { ICoverLetter, IResume } from '../shared/types'
import convertURIToBlob from './convertURIToBlob'

const uploadFileToInputField = (
  document: IResume | ICoverLetter,
  dataURL,
  inputField: HTMLInputElement,
) => {
  const blob = convertURIToBlob(dataURL)
  const file = new File(
    [blob],
    `${document.type === 'cover_letter' ? DEFAULT_COVER_LATTER_NAME(document as ICoverLetter) : DEFAULT_RESUME_NAME(document as IResume)}.${RESUME_FORMAT.PDF}`,
    {
      type: blob.type,
    },
  )

  const fileList = new DataTransfer()
  fileList.items.add(file)

  inputField.files = fileList.files

  const inputEvent = new Event('change', { bubbles: true })
  inputField.dispatchEvent(inputEvent)
}

export default uploadFileToInputField
