import { AutofillPayload } from '../../shared/types'
import { BaseAutofillStrategy } from './baseAutofill.strategy'

export class GreenHouseAutofillStrategy implements BaseAutofillStrategy {
  getFillableFields(): HTMLInputElement[] {
    throw new Error('Method not implemented.')
  }
  static BOARD_URL = 'https://boards.greenhouse.io'

  autoFillApplication({ user, resume, resumeFileDataUrl }: AutofillPayload): void {
    const firstNameElement: HTMLInputElement | null = document.querySelector(
      '#application_form #first_name',
    )
    const lastNameElement: HTMLInputElement | null = document.querySelector(
      '#application_form #last_name',
    )
    const phoneElement: HTMLInputElement | null = document.querySelector('#application_form #phone')
    const emailElement: HTMLInputElement | null = document.querySelector('#application_form #email')
    const locationElement: HTMLInputElement | null = document.querySelector(
      '#application_form #job_application_location #auto_complete_input',
    )
    if (firstNameElement && resume.firstName) firstNameElement.value = resume.firstName
    if (lastNameElement && resume.lastName) lastNameElement.value = resume.lastName
    if (phoneElement && resume.phoneNumber) phoneElement.value = resume.phoneNumber
    if (emailElement && resume.email) emailElement.value = resume.email
    if (emailElement && resume.email) emailElement.value = resume.email
    if (locationElement && resume.city) locationElement.value = resume.city

    // Todo Upload file into job application
    locationElement?.focus()
  }

  canAutofill(): boolean {
    const elements = document.querySelectorAll('[action]')

    let isGreenhouseJob = false
    elements.forEach((element) => {
      if (element.getAttribute('action')?.includes(GreenHouseAutofillStrategy.BOARD_URL)) {
        isGreenhouseJob = true
      }
    })

    return isGreenhouseJob
  }
}
