import { AutofillPayload } from '../../shared/types'
import uploadFileToInputField from '../../utils/uploadFileToInputField'
import { BaseAutofillStrategy } from './baseAutofill.strategy'

export class LeverAutofillStrategy implements BaseAutofillStrategy {
  getFillableFields(): HTMLInputElement[] {
    throw new Error('Method not implemented.')
  }
  static BOARD_URL = 'https://jobs.lever.co'

  autoFillApplication({
    user,
    resume,
    resumeFileDataUrl,
    coverLetterDataUrl,
  }: AutofillPayload): void {
    // TODO: Load this mapping from some config variable
    const nameElement: HTMLInputElement | null = document.querySelector(
      '#application-form input[name="name"]',
    )
    const emailElement: HTMLInputElement | null = document.querySelector(
      '#application-form input[name="email"]',
    )
    const phoneElement: HTMLInputElement | null = document.querySelector(
      '#application-form input[name="phone"]',
    )
    const locationElement: HTMLInputElement | null = document.querySelector(
      '#application-form input[name="location"]',
    )
    const orgElement: HTMLInputElement | null = document.querySelector(
      '#application-form input[name="org"]',
    )
    const linkedInElement: HTMLInputElement | null = document.querySelector(
      '#application-form input[name="urls[LinkedIn]"]',
    )
    const fileInput = document.getElementById('resume-upload-input') as HTMLInputElement | null

    if (nameElement && resume.name && resumeFileDataUrl) nameElement.value = resume.name
    if (emailElement && resume.email) emailElement.value = resume.email
    if (phoneElement && resume.phoneNumber) phoneElement.value = resume.phoneNumber
    if (locationElement && resume.city) locationElement.value = resume.city
    if (orgElement && resume.employerName) orgElement.value = resume.employerName
    if (linkedInElement && resume.linkedin) linkedInElement.value = resume.linkedin

    if (resumeFileDataUrl && fileInput) {
      uploadFileToInputField(resume, resumeFileDataUrl, fileInput)
    }

    locationElement?.focus()
  }

  canAutofill(): boolean {
    const elements = document.querySelectorAll('[content]')

    let isLeverJob = false
    elements.forEach((element) => {
      if (element.getAttribute('content')?.includes(LeverAutofillStrategy.BOARD_URL)) {
        isLeverJob = true
      }
    })

    return isLeverJob
  }
}
