import extractJwt from './extractJwt'
import insertIframe from './insertIframe'
import { SIGN_IN_PATH, SUPPORTED_APP_DOMAINS, EXTENSION_LOGIN_PATH } from '../shared/constants'

if (
  [...SUPPORTED_APP_DOMAINS.map(domain => `${domain}${EXTENSION_LOGIN_PATH}`), ...SUPPORTED_APP_DOMAINS.map(domain => `${domain}${SIGN_IN_PATH}`)].includes(window.location.href)
) {
  extractJwt()
} else {
  insertIframe()
}
