/*global chrome*/
import { BUS_SENDER, BUS_EVENT_NAMES } from '../shared/constants'
import { AutofillPayload } from '../shared/types'
import { TAB_MESSAGE_TYPES } from './constants'
import strategies from './strategies'

const insertIframe = (): void => {
  const frame = document.createElement('iframe')
  frame.id = 'jtrack-root'
  frame.src = chrome.runtime.getURL('app.html')

  document.body.appendChild(frame)

  frame.style.display = 'none'

  chrome.runtime.onMessage.addListener(function (request, sender, sendResponse) {
    switch (request.type) {
      case TAB_MESSAGE_TYPES.toggleExtensionWindow:
        toggle()
        return
      case TAB_MESSAGE_TYPES.sendJwt:
        frame.contentWindow?.postMessage(
          {
            sender: BUS_SENDER,
            name: BUS_EVENT_NAMES.setJwt,
            token: request.token,
            refreshToken: request.refreshToken,
            baseDomain: request.baseDomain,
            isRioUser: request.isRioUser
          },
          '*',
        )
        return
      case TAB_MESSAGE_TYPES.autofill:
        autofill({
          resume: request.resume,
          user: request.user,
          resumeFileDataUrl: request.resumeFileDataUrl,
          coverLetterDataUrl: request.coverLetterDataUrl,
        })
        return
    }
  })

  async function autofill(userData: AutofillPayload) {
    for (const strategy of strategies) {
      if (strategy.canAutofill()) {
        strategy.autoFillApplication(userData)
        break
      }
    }
  }

  function toggle() {
    if (frame.style.display === 'none') {
      frame.style.display = 'block'
    } else {
      frame.style.display = 'none'
    }
  }
}

export default insertIframe
