import { AutofillPayload, ResumeFieldMapping } from '../../shared/types'
import uploadFileToInputField from '../../utils/uploadFileToInputField'
import stringContainsOneOfArrayElements from '../../utils/stringContainsOneOfArrayElements'
import { BaseAutofillStrategy } from './baseAutofill.strategy'

export class CommonAutofillStrategy implements BaseAutofillStrategy {
  getFillableFields(): HTMLInputElement[] {
    throw new Error('Method not implemented.')
  }
  fieldMapping(): ResumeFieldMapping {
    return {
      employerName: ['org'],
      name: [],
      firstName: ['first_name'],
      lastName: ['last_name'],
      phoneNumber: ['phone'],
      countryName: ['country', 'country_name'],
      nationality: [],
      email: [],
      gender: [],
      married: ['is_married'],
      birthDate: ['birth_date'],
      city: [],
      address: [],
      postalCode: ['zip'],
      linkedin: ['urls[LinkedIn]'],
      resume: ['cv'],
      coverLetter: ['cover_letter'],
    }
  }
  autoFillApplication({ resume, resumeFileDataUrl }: AutofillPayload): void {
    this.autofillTextFields(resume)
    this.autofillCheckboxes(resume)
    this.autofillEmailFields(resume)
    this.autofillFiles(resume, resumeFileDataUrl)
  }

  autofillTextFields(resume) {
    const inputFields = document.querySelectorAll('input[type="text"]')
    const telFields = document.querySelectorAll('input[type="tel"]')
    inputFields.forEach((input: any) => {
      const attributeName = input.getAttribute('name')
      const fieldName = this.findMatchingFieldName(attributeName)
      if (fieldName && resume[fieldName] !== undefined) {
        input.value = resume[fieldName]
      }
    })

    telFields.forEach((input: any) => {
      const attributeName = input.getAttribute('name')
      const fieldName = this.findMatchingFieldName(attributeName)
      if (fieldName && resume[fieldName] !== undefined) {
        input.value = resume[fieldName]
      }
    })
  }

  autofillFiles(resume, resumeFileDataUrl) {
    const fieldInputs = document.querySelectorAll('input[type="file"]')
    fieldInputs.forEach((input) => {
      const attributeName = input.getAttribute('name')
      const fieldName = this.findMatchingFieldName(attributeName)
      if (fieldName && fieldName === 'resume') {
        uploadFileToInputField(resume, resumeFileDataUrl, input as HTMLInputElement)
      }
      if (fieldName && fieldName === 'coverLetter') {
        //TODO: upload cover letter
      }
    })
  }

  autofillEmailFields(resume) {
    const emailFields = document.querySelectorAll('input[type="email"]')
    emailFields.forEach((input: any) => {
      const attributeName = input.getAttribute('name')
      const fieldName = this.findMatchingFieldName(attributeName)
      if (fieldName && resume[fieldName] !== undefined) {
        input.value = resume[fieldName]
      }
    })
  }

  autofillCheckboxes(resume) {
    const checkboxFields = document.querySelectorAll('input[type="checkbox"]')
    checkboxFields.forEach((checkbox: any) => {
      const attributeName = checkbox.getAttribute('name')
      const fieldName = this.findMatchingFieldName(attributeName)
      if (fieldName && resume[fieldName] !== undefined) {
        checkbox.checked = !!resume[fieldName]
      }
    })
  }

  findMatchingFieldName(attributeName: string | null) {
    const fieldMappings = this.fieldMapping()
    for (const fieldName in fieldMappings) {
      const names = [fieldName, ...fieldMappings[fieldName]]
      if (attributeName && stringContainsOneOfArrayElements(attributeName, names)) {
        return fieldName
      }
    }
  }

  canAutofill(): boolean {
    return true
  }
}
